/// <summary>
/// Extension of <c>PurchPackingSlipJournalCreate</c> carrying the PSS import folder
/// reference onto the created packing slip journal. Upgraded from the AX 2012
/// VAR-layer member added by PSS-001-IMPORTFOLDER.
/// </summary>
[ExtensionOf(classStr(PurchPackingSlipJournalCreate))]
final class PSSPurchPackingSlipJournalCreate_Extension
{
    private RefRecId pssImpFolderTableRecId;
}

Method.Source:
/// <summary>
/// Gets or sets the record ID of the PSS import folder that the posting originates from.
/// </summary>
/// <param name = "_pssImpFolderTableRecId">The import folder record ID.</param>
/// <returns>The import folder record ID.</returns>
public RefRecId pssParmImpFolderTableRecId(RefRecId _pssImpFolderTableRecId = pssImpFolderTableRecId)
{
    pssImpFolderTableRecId = _pssImpFolderTableRecId;
    return pssImpFolderTableRecId;
}
